using System.Collections.Concurrent;

var auftraege =
  new BlockingCollection<string>(
      boundedCapacity: 2);

var drucker = Task.Run(() =>
{
  foreach (var a in auftraege
      .GetConsumingEnumerable())
  {
    Thread.Sleep(50);
    Console.WriteLine($"Druck: {a}");
  }
  Console.WriteLine("Drucker aus");
});

for (int i = 1; i <= 4; i++)
  auftraege.Add($"Blatt {i}");
auftraege.CompleteAdding();
drucker.Wait();

using System.Threading.Channels;

var kanal =
    Channel.CreateBounded<int>(10);
var leser = Task.Run(async () =>
{
    int s = 0;
    await foreach (var x in
        kanal.Reader.ReadAllAsync())
        s += x;
    return s;
});
for (int i = 1; i <= 10; i++)
    await kanal.Writer.WriteAsync(i);
kanal.Writer.Complete();
Console.WriteLine(await leser); // 55
